actions.script:
// Unanswered first, newest first within each (the find is already newest first; the sort is stable).
List ordered = rows.sort(false) { a, b -> (a.answeredStamp != null ? 1 : 0) <=> (b.answeredStamp != null ? 1 : 0) }
int max = Math.max(1, (limit ?: 50) as int)
if (ordered.size() > max) ordered = ordered.subList(0, max)
long now = ec.user.nowTimestamp.time
Map tenantNames = [:]
Map userNames = [:]
Map statementCodes = [:]
ordered.each { r ->
    String t = r.companyUserGroupId
    if (!tenantNames.containsKey(t)) {
        def g = ec.entity.find("moqui.security.UserGroup").condition("userGroupId", t).useCache(false).one()
        tenantNames[t] = g?.description ?: t
    }
    String u = r.sentByUserId
    if (!userNames.containsKey(u)) {
        def a = ec.entity.find("moqui.security.UserAccount").condition("userId", u).useCache(false).one()
        userNames[u] = a?.userFullName ?: a?.username ?: u
    }
    String sid = r.statementId
    if (!statementCodes.containsKey(sid)) {
        def s = ec.entity.find("darpan.audit.AuditStatement").condition("statementId", sid).useCache(false).one()
        statementCodes[sid] = s?.statementCode ?: sid
    }
}
feedback = ordered.collect { r ->
    [feedbackId: r.feedbackId, tenant: [id: r.companyUserGroupId, name: tenantNames[r.companyUserGroupId]],
     statement: statementCodes[r.statementId], cause: r.conclusionCode, record: r.recordKey, note: r.note,
     sentBy: userNames[r.sentByUserId], sentAt: ((java.sql.Timestamp) r.sentStamp).toInstant().toString(),
     ageDays: Math.max(0L, (now - ((java.sql.Timestamp) r.sentStamp).time).intdiv(86400000L)),
     answer: r.answer, answeredAt: r.answeredStamp != null ? ((java.sql.Timestamp) r.answeredStamp).toInstant().toString() : null]
}
